import React from 'react';

import { selectProductAsync } from '@apps/Products/components/ProductSelectModal/productSelectModalHelper';
import { success } from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';
import PohButton from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput, { InputSizes, InputTypes } from '@ui-kit/Input';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import {
  addRecipeStructureProduct,
  deleteRecipeStructureProduct,
  getRecipeStructureProducts,
  updateRecipeStructureProduct,
} from '../../@services/recipes.service';
import { IFullRecipe, IRecipeStructureProduct } from '../../@types/recipes.types';

interface IRecipeEditStructureProps {
  recipeData?: IFullRecipe;
  id_recipe: number;
}

const RecipeEditStructure: React.FC<IRecipeEditStructureProps> = ({ id_recipe, recipeData }) => {
  const [err, setErr] = React.useState<Error>();
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IRecipeStructureProduct[]>([]);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const rsd = await getRecipeStructureProducts(id_recipe);
        setData(rsd);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [recipeData, id_recipe]);

  if (isLoading) {
    return (
      <div className="m-6 p-6 text-center">
        <PohLoader />
      </div>
    );
  }

  if (err) {
    return <PohAlert>{err.message}</PohAlert>;
  }

  return (
    <div>
      <PohList
        data={data.map((d) => {
          return {
            key: d.id_recipes_structure,
            className: 'py-1',
            children: (
              <div className="d-flex align-items-center" style={{ gap: 12 }}>
                <strong className="flex-grow-1">{d.name}</strong>
                <PohInput
                  style={{ width: 100 }}
                  size={InputSizes.Small}
                  type={InputTypes.number}
                  value={d.amount ? d.amount.toString() : ''}
                  onRealChange={async (v, e) => {
                    const amount = parseInt(v);

                    const inp = e.target as HTMLInputElement;
                    inp.disabled = true;

                    await updateRecipeStructureProduct(d.id_recipes_structure, amount);

                    setData((cur) => cur.map((c) => (c.id === d.id ? { ...c, amount } : c)));
                    success('Обновлено');

                    inp.disabled = false;
                  }}
                  onChange={async (v) => {
                    const amount = parseInt(v);

                    setData((cur) => cur.map((c) => (c.id === d.id ? { ...c, amount } : c)));
                  }}
                />
                <PohButton
                  icon={IconsEnum.trash}
                  onClick={async (e) => {
                    const btn = e.target as HTMLButtonElement;
                    btn.disabled = true;
                    if (await confirmModal2(`Удалить "${d.name}"?`)) {
                      await deleteRecipeStructureProduct(d.id_recipes_structure);
                      setData((cur) => cur.filter((c) => c.id !== d.id));
                      success('Удалено');
                    }

                    btn.disabled = false;
                  }}
                />
              </div>
            ),
          };
        })}
      />
      <PohButton
        onClick={async (e) => {
          const btn = e.target as HTMLButtonElement;
          btn.disabled = true;
          const selectedProduct = await selectProductAsync(data.map((d) => d.id_product));
          const newId = await addRecipeStructureProduct(id_recipe, selectedProduct.id);
          const newRecipeProduct: IRecipeStructureProduct = {
            id: selectedProduct.id,
            id_recipes_structure: newId,
            name: selectedProduct.name,
            carbs: selectedProduct.carbs,
            protein: selectedProduct.protein,
            fat: selectedProduct.fat,
            energy: selectedProduct.energy,
            amount: 0,
            kkal: 0,
            id_product: selectedProduct.id,
          };
          setData((cur) => [...cur, newRecipeProduct]);
          success('Ингредиент добавлен');

          btn.disabled = false;
        }}
      >
        Добавить
      </PohButton>
    </div>
  );
};

export default RecipeEditStructure;
