import React, { useState } from 'react';

import cn from 'clsx';

import { success } from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohImageUploader from '@ui-kit/ImageUploader';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohLoader from '@ui-kit/Loader';

import { getRecipeByIdAsync, updateRecipeAsync } from '../../@services/recipes.service';
import { IUpdateRecipeDTO } from '../../@types/recipes.backTypes';
import { IFullRecipe } from '../../@types/recipes.types';
import SelectRecipeCategory from '../SelectRecipeCategory';

interface IRecipeEditBaseParamsProps {
  recipeData?: IFullRecipe;
  id_recipe: number;
}

const RecipeEditBaseParams: React.FC<IRecipeEditBaseParamsProps> = ({ id_recipe, recipeData }) => {
  const [isSaving, setIsSaving] = React.useState(false);
  const [err, setErr] = React.useState<Error>();

  const [isLoading, setIsLoading] = React.useState(true);

  const [formData, setFormData] = useState<IUpdateRecipeDTO>();

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const rd = recipeData ?? (await getRecipeByIdAsync(id_recipe));
        setFormData({
          id: rd.id,
          name: rd.name,
          promo: rd.promo,
          text: rd.text,
          photo: rd.photo,
          id_category: rd.category.id,
          gas_count: rd.gas_count,
          water_count: rd.water_count,
          cooking_time: rd.cooking_time,
        });
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [recipeData, id_recipe]);

  if (isLoading) {
    return (
      <div className="m-6 p-6 text-center">
        <PohLoader />
      </div>
    );
  }

  const submitFormHandler = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      setIsSaving(true);
      if (!formData) throw new Error('has no formData');

      await updateRecipeAsync(formData).then(() => {
        success('Рецепт успешно обновлен');
      });
    } catch (er) {
      setErr(er as Error);
    } finally {
      setIsSaving(false);
    }
  };
  type T = Omit<IUpdateRecipeDTO, 'id'>;

  const handleInputChange =
    <K extends keyof T>(field: keyof T) =>
    (value: T[K]) => {
      setFormData((fd) => ({
        ...(fd as IUpdateRecipeDTO),
        [field]: value,
      }));
    };

  if (err) {
    return <PohAlert>{err.message}</PohAlert>;
  }

  return (
    <form onSubmit={submitFormHandler} className={cn('mt-4', 'qa-hiking-base-info-form')}>
      <PohRow className="mb-2">
        <PohCol sm={12}>
          <SelectRecipeCategory
            value={formData?.id_category}
            onChange={(v) => handleInputChange('id_category')(v?.id ? v.id : 1)}
          />
        </PohCol>
      </PohRow>
      <PohRow className="mb-2">
        <PohCol sm={12}>
          <PohInput
            horizontal
            label="Название"
            placeholder="Название рецепта"
            required
            value={formData?.name}
            name="name_recipe"
            id="name_recipe"
            onChange={handleInputChange('name')}
            autoFocus
          />
        </PohCol>
      </PohRow>
      <PohRow className="mb-2">
        <PohCol sm={12}>
          <PohInput
            horizontal
            type={InputTypes.textarea}
            label="Краткое описание"
            placeholder="Краткое описание рецепта (тизер)"
            required
            value={formData?.promo}
            name="recipe-promo_text"
            id="recipe-promo_text"
            onChange={handleInputChange('promo')}
          />
        </PohCol>
      </PohRow>
      <PohRow className="mb-2">
        <PohCol sm={12}>
          <PohInput
            horizontal
            type={InputTypes.textarea}
            label="Полное описание"
            placeholder="Полное описание рецепт"
            value={formData?.text}
            name="recipe-text"
            id="recipe-text"
            onChange={handleInputChange('text')}
          />
        </PohCol>
      </PohRow>
      <PohRow className="mb-2">
        <PohCol sm={2}></PohCol>

        <PohCol sm={3}>
          <PohInput
            type={InputTypes.number}
            label="Приг-ие (минут)"
            value={formData?.cooking_time ? formData.cooking_time.toString() : ''}
            name="recipe-time"
            id="recipe-time"
            onChange={handleInputChange('cooking_time')}
            max={600}
          />
        </PohCol>
        <PohCol sm={3}>
          <PohInput
            type={InputTypes.number}
            label="Кол-во воды (мл)"
            value={formData?.water_count ? formData.water_count.toString() : ''}
            name="recipe-water_count"
            id="recipe-water_count"
            onChange={handleInputChange('water_count')}
            max={4999}
          />
        </PohCol>
        <PohCol sm={3}>
          <PohInput
            type={InputTypes.number}
            label="Кол-во газа (г)"
            value={formData?.gas_count ? formData.gas_count.toString() : ''}
            max={999}
            name="recipe-gas_count"
            id="recipe-gas_count"
            onChange={handleInputChange('gas_count')}
          />
        </PohCol>
      </PohRow>
      <PohRow className="mb-2">
        <PohCol sm={2}>Изображение</PohCol>
        <PohCol sm={10}>
          <div style={{ width: 255, height: 255, maxHeight: 256, overflow: 'auto' }}>
            <PohImageUploader
              folder="images/recipes"
              name={`recipe_${id_recipe}`}
              validation={{ maxHeight: 7777, maxWidth: 5555, size: 10024288 }}
              width={255}
              height={255}
              src={formData?.photo}
              onChange={(src) => {
                handleInputChange('photo')(src ?? '');
              }}
            />
          </div>
        </PohCol>
      </PohRow>
      <PohRow className="mb-4 mt-2">
        <PohCol sm={2} />
        <PohCol sm={10}>
          <PohButton
            variant={ButtonVariant.Primary}
            disabled={isSaving}
            onClick={() => {}}
            className="w-100"
            type="submit"
          >
            Сохранить
          </PohButton>
        </PohCol>
      </PohRow>
    </form>
  );
};

export default RecipeEditBaseParams;
